<?php
require_once __DIR__.'/../includes/db.php'; require_once __DIR__.'/../includes/functions.php'; require_admin();
if($_SERVER['REQUEST_METHOD']==='POST') { verify_csrf(); $action=$_POST['action']??''; if($action==='delete') { db()->prepare('DELETE FROM courses WHERE id=?')->execute([(int)$_POST['id']]); flash('Course deleted.'); redirect('courses.php'); }
$title=trim($_POST['title']??''); $desc=trim($_POST['description']??''); $category=trim($_POST['category']??'General'); $level=$_POST['level']??'Beginner'; $hours=max(1,(int)($_POST['duration_hours']??1));
if($title!=='' && $desc!=='') { db()->prepare("INSERT INTO courses(title,description,category,level,duration_hours,status,instructor_id) VALUES(?,?,?,?,?,'published',?)")->execute([$title,$desc,$category,$level,$hours,current_user()['id']]); flash('Course added.'); redirect('courses.php'); } flash('Title and description are required.','error'); redirect('courses.php'); }
$rows=db()->query('SELECT id,title,category,level FROM courses ORDER BY created_at DESC')->fetchAll(); $page_title='Manage courses'; require __DIR__.'/../includes/header.php'; ?>
<section class="page-heading"><p class="eyebrow">ADMIN TOOLS</p><h1>Manage courses</h1></section><div class="panel"><h2>Add a course</h2><form method="post" class="form-grid"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><label>Course title<input name="title" required maxlength="180"></label><label>Category<input name="category" required value="General"></label><label>Level<select name="level"><option>Beginner</option><option>Intermediate</option><option>Advanced</option></select></label><label>Duration (hours)<input type="number" name="duration_hours" min="1" value="2"></label><label class="span-all">Description<textarea name="description" rows="3" required></textarea></label><div class="span-all"><button class="button">Add course</button></div></form></div>
<div class="panel"><h2>Course catalogue</h2><div class="table-wrap"><table><thead><tr><th>Title</th><th>Category</th><th>Level</th><th>Action</th></tr></thead><tbody><?php foreach($rows as $r): ?><tr><td><?= e($r['title']) ?></td><td><?= e($r['category']) ?></td><td><?= e($r['level']) ?></td><td><form method="post" onsubmit="return confirm('Delete this course?')"><input type="hidden" name="csrf_token" value="<?= e(csrf_token()) ?>"><input type="hidden" name="action" value="delete"><input type="hidden" name="id" value="<?= (int)$r['id'] ?>"><button class="button danger small">Delete</button></form></td></tr><?php endforeach; ?></tbody></table></div></div>
<?php require __DIR__.'/../includes/footer.php'; ?>
